 "content": "from collections import deque

def transform(grid):
    """Recolor a singleton object when it is vertically aligned over a larger object."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))
    out = [row[:] for row in grid]
    # A one-cell marker aligned in a column with an object below takes that object's color.
    candidates = []
    for color, cells in comps:
        if len(cells) != 1:
            continue
        r, c = cells[0]
        below = [(co, cs) for co, cs in comps if co != color and any(y > r and x == c for y, x in cs)]
        if below:
            co, cs = min(below, key=lambda item: min(y for y, x in item[1] if x == c))
            candidates.append((r, c, co))
    if candidates:
        r, c, co = candidates[0]
        out[r][c] = co
    return out
